INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('06f7fe4a-b57c-4de3-824e-077498605e82','e9ebefcd-c496-45e8-b816-a79f8442ba85',3.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('06f7fe4a-b57c-4de3-824e-077498605e82','e9ebefcd-c496-45e8-b816-a79f8442ba85',$$Council Member Macedo, an attorney, calls for "practical, lawful solutions that protect public safety while preserving quality of life," pairing safety concerns (theft, traffic) with attention to constitutional rights — a balanced, rights-conscious approach.$$,ARRAY['https://aida4whittier.com/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('06f7fe4a-b57c-4de3-824e-077498605e82','fb25c1ac-91cc-49bf-8afc-c7fa22ef45e4',4.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('06f7fe4a-b57c-4de3-824e-077498605e82','fb25c1ac-91cc-49bf-8afc-c7fa22ef45e4',$$Macedo argues growth "should serve families, seniors, and small businesses — not special interests," stresses she is "not a developer," and pledges residents will always be her priority — a resident-first, developer-skeptical growth stance.$$,ARRAY['https://aida4whittier.com/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('06f7fe4a-b57c-4de3-824e-077498605e82','eb3d1247-0de1-4b7f-baec-7259861efd53',2.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('06f7fe4a-b57c-4de3-824e-077498605e82','eb3d1247-0de1-4b7f-baec-7259861efd53',$$Macedo proposed a grant program to revitalize storefronts and help small businesses make payroll, an active small-business economic-development position.$$,ARRAY['https://aida4whittier.com/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
